//! Exclusion mode (`fast_hrv::exclusion`).
//!
//! 1. Equivalence with the Python research reference (`tests/data/exclusion_reference.json`,
//!    generated by `tools/exclusion_reference.py` on synthetic series only): output positions,
//!    ectopic (Kubios-mapped and pattern), suspect beats and their required move, disagreement,
//!    excluded NN, inserted / removed counts, single- and two-stage, alpha 5.2 / 6, floor 40 ms.
//! 2. Synthetic series with injected premature + compensatory ectopic beats, missed and extra beats
//!    and fiducial jitter: classification, NN mask and RMSSD accuracy.

use fast_hrv::exclusion::{BeatClass, BeatExclusion, ExclusionParams, classify_beats};
use fast_hrv::hrv::compute_rmssd;
use fast_hrv::peaks::{KubiosParams, fix_positions_with};
use fast_hrv::rri_from_positions;
use serde_json::Value;

// ---------------------------------------------------------------------------------------------
// 1. Python reference
// ---------------------------------------------------------------------------------------------

fn load(name: &str) -> Value {
    let path = format!("{}/tests/data/{name}", env!("CARGO_MANIFEST_DIR"));
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    serde_json::from_str(&text).unwrap()
}

fn usizes(v: &Value) -> Vec<usize> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_u64().unwrap() as usize)
        .collect()
}

fn f64s_from_bits(v: &Value) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| f64::from_bits(x.as_u64().unwrap()))
        .collect()
}

fn from_delta(input: &[f64], d: &Value) -> Vec<f64> {
    let removed = usizes(&d["removed"]);
    let mut out: Vec<f64> = input
        .iter()
        .enumerate()
        .filter(|(i, _)| !removed.contains(i))
        .map(|(_, &p)| p)
        .collect();
    for a in d["added"].as_array().unwrap() {
        out.push(f64::from_bits(a[1].as_u64().unwrap()));
    }
    out.sort_by(f64::total_cmp);
    out
}

fn set_indices(it: impl Iterator<Item = bool>) -> Vec<usize> {
    it.enumerate().filter(|(_, b)| *b).map(|(i, _)| i).collect()
}

#[test]
fn matches_python_reference() {
    let r = load("exclusion_reference.json");
    let (mut runs, mut ect, mut sus2) = (0, 0, 0);
    for case in r["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let fs = case["sampling_rate"].as_f64().unwrap();
        let pos = f64s_from_bits(&case["positions"]);
        let dis_idx = usizes(&case["disagreement"]);
        let dis: Vec<bool> = (0..pos.len()).map(|i| dis_idx.contains(&i)).collect();
        for (key, e) in case["runs"].as_object().unwrap() {
            let label = format!("{name} {key}");
            let params = ExclusionParams {
                kubios: KubiosParams {
                    alpha: e["alpha"].as_f64().unwrap(),
                    threshold_floor_s: e["floor_s"].as_f64().unwrap(),
                    ..Default::default()
                },
                two_stage: e["two_stage"].as_bool().unwrap(),
                // the research reference keeps the NN around inserted / removed beats
                exclude_inserted_removed: false,
                ..Default::default()
            };
            let d = e["with_disagreement"]
                .as_bool()
                .unwrap()
                .then_some(dis.as_slice());
            let out = classify_beats(&pos, fs, &params, d).unwrap();
            let expected = from_delta(&pos, &e["positions"]);
            assert_eq!(out.positions.len(), expected.len(), "{label}");
            assert!(
                out.positions
                    .iter()
                    .zip(&expected)
                    .all(|(a, b)| a.to_bits() == b.to_bits()),
                "{label}: positions"
            );
            let b = &out.beats;
            assert_eq!(
                set_indices(b.iter().map(|x| x.is_ectopic())),
                usizes(&e["ectopic"]),
                "{label}: ectopic"
            );
            assert_eq!(
                set_indices(b.iter().map(|x| x.ectopic_kubios)),
                usizes(&e["kubios_ectopic"]),
                "{label}: Kubios-mapped ectopic"
            );
            assert_eq!(
                set_indices(b.iter().map(|x| x.ectopic_pattern)),
                usizes(&e["pattern"]),
                "{label}: pattern"
            );
            assert_eq!(
                set_indices(b.iter().map(|x| x.is_suspect())),
                usizes(&e["suspect"]),
                "{label}: suspect"
            );
            assert_eq!(
                set_indices(b.iter().map(|x| x.disagreement)),
                usizes(&e["disagreement"]),
                "{label}: disagreement"
            );
            for m in e["suspect_move_ms"].as_array().unwrap() {
                let j = m[0].as_u64().unwrap() as usize;
                let want = f64::from_bits(m[1].as_u64().unwrap()) / 1000.0;
                let got = b[j].suspect_move_s;
                assert!(
                    (want.is_infinite() && got == want)
                        || (got - want).abs() <= 1e-12 * want.abs().max(1e-3),
                    "{label}: beat {j} move {got} vs {want}"
                );
            }
            assert_eq!(
                set_indices(out.nn_valid.iter().map(|v| !v)),
                usizes(&e["excluded_nn"]),
                "{label}: excluded NN"
            );
            let c = out.artifact_counts();
            assert_eq!(c.inserted, e["inserted"].as_u64().unwrap() as usize);
            assert_eq!(c.removed, e["removed"].as_u64().unwrap() as usize);

            // default (exclude inserted / removed): a superset of the excluded NN
            let strict = classify_beats(
                &pos,
                fs,
                &ExclusionParams {
                    exclude_inserted_removed: true,
                    ..params
                },
                d,
            )
            .unwrap();
            assert!(
                strict
                    .nn_valid
                    .iter()
                    .zip(&out.nn_valid)
                    .all(|(s, o)| !*s || *o),
                "{label}"
            );
            runs += 1;
            ect += out.ectopic_count();
            sus2 += b.iter().filter(|x| x.suspect_stage == 2).count();
        }
    }
    eprintln!(
        "Python reference: {runs} runs identical ({ect} ectopic beats, {sus2} stage-2 suspects)"
    );
    assert!(runs >= 100);
    assert!(sus2 > 0, "the reference must exercise the two-stage pass");
}

// ---------------------------------------------------------------------------------------------
// 2. synthetic series with injected events
// ---------------------------------------------------------------------------------------------

pub const FS: f64 = 512.0;

pub struct Lcg(pub u64);
impl Lcg {
    pub fn uniform(&mut self) -> f64 {
        self.0 = self
            .0
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        ((self.0 >> 11) as f64 + 0.5) / (1u64 << 53) as f64
    }
    pub fn normal(&mut self) -> f64 {
        let (u, v) = (self.uniform(), self.uniform());
        (-2.0 * u.ln()).sqrt() * (2.0 * std::f64::consts::PI * v).cos()
    }
}

/// Sinus rhythm (known truth): mean RR + RSA (0.25 Hz) + LF (0.1 Hz) + AR(1) noise, all in ms.
/// Positions in samples at [`FS`].
pub fn sinus(seed: u64, n: usize, mean: f64, rsa: f64, lf: f64, noise: f64) -> Vec<f64> {
    let mut rng = Lcg(seed ^ 0x9e37_79b9_7f4a_7c15);
    let tau = std::f64::consts::TAU;
    let (p1, p2) = (rng.uniform() * tau, rng.uniform() * tau);
    let (mut t, mut e) = (0.0, 0.0);
    let mut pos = Vec::with_capacity(n);
    pos.push(1000.0);
    while pos.len() < n {
        e = 0.3 * e + noise * rng.normal();
        let rr = mean + rsa * (tau * 0.25 * t + p1).sin() + lf * (tau * 0.1 * t + p2).sin() + e;
        t += rr / 1000.0;
        pos.push(pos.last().unwrap() + rr * FS / 1000.0);
    }
    pos
}

/// Injected series, events (kind, footprint start, footprint end), ectopic beat positions.
pub type Injected = (Vec<f64>, Vec<(Event, f64, f64)>, Vec<f64>);

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Event {
    Ectopic,
    Missed,
    Extra,
    Jitter,
}

/// Inject `n_ect` ectopic beats (20–35 % premature, full compensation) and `n_art` artifacts
/// (missed / extra / jitter ±20–50 ms, equally likely), at least 3 beats apart. Returns the series
/// and, per event, its kind and the positions [T[c−1], T[c+1]] of its footprint; for ectopic beats
/// also the injected position.
pub fn inject(truth: &[f64], n_ect: usize, n_art: usize, seed: u64) -> Injected {
    let mut rng = Lcg(seed.wrapping_mul(31) + 7);
    let n = truth.len();
    let mut chosen: Vec<usize> = Vec::new();
    let mut tries = 0;
    while chosen.len() < n_ect + n_art && tries < 100_000 {
        tries += 1;
        let c = 2 + (rng.uniform() * (n - 4) as f64) as usize;
        if chosen.iter().all(|&x| x.abs_diff(c) >= 3) {
            chosen.push(c);
        }
    }
    let mut x: Vec<f64> = truth.to_vec();
    let mut delete = Vec::new();
    let mut add = Vec::new();
    let mut events = Vec::new();
    let mut ectopic_pos = Vec::new();
    for (k, &c) in chosen.iter().enumerate() {
        let (prev, cur) = (truth[c - 1], truth[c]);
        let kind = if k < n_ect {
            Event::Ectopic
        } else {
            [Event::Missed, Event::Extra, Event::Jitter][(rng.uniform() * 3.0) as usize % 3]
        };
        match kind {
            Event::Ectopic => {
                x[c] = cur - (0.20 + 0.15 * rng.uniform()) * (cur - prev);
                ectopic_pos.push(x[c]);
            }
            Event::Missed => delete.push(c),
            Event::Extra => add.push(prev + (0.3 + 0.4 * rng.uniform()) * (cur - prev)),
            Event::Jitter => {
                let s = if rng.uniform() < 0.5 { -1.0 } else { 1.0 };
                x[c] = cur + s * (20.0 + 30.0 * rng.uniform()) * FS / 1000.0;
            }
        }
        events.push((kind, truth[c - 1], truth[c + 1]));
    }
    let mut out: Vec<f64> = x
        .iter()
        .enumerate()
        .filter(|(i, _)| !delete.contains(i))
        .map(|(_, &p)| p)
        .chain(add)
        .collect();
    out.sort_by(f64::total_cmp);
    out.dedup();
    (out, events, ectopic_pos)
}

/// Input index of every injected ectopic beat.
fn ectopic_inputs(x: &[f64], ectopic_pos: &[f64]) -> Vec<usize> {
    ectopic_pos
        .iter()
        .map(|p| x.iter().position(|q| q == p).unwrap())
        .collect()
}

/// Did the exclusion mode act on the footprint of each artifact event (a flagged, inserted or
/// removed beat inside [T[c−1], T[c+1]])?
fn caught(out: &BeatExclusion, x: &[f64], lo: f64, hi: f64) -> bool {
    let inr = |p: f64| p >= lo && p <= hi;
    out.beats
        .iter()
        .zip(&out.positions)
        .any(|(b, &p)| inr(p) && (b.is_ectopic() || b.is_suspect() || b.inserted || b.disagreement))
        || out.removed.iter().any(|r| inr(x[r.input_index]))
}

#[test]
fn injected_ectopic_beats_are_classified_ectopic() {
    let params = ExclusionParams::default();
    let (mut n_ect, mut n_hit, mut n_art, mut n_art_hit) = (0, 0, 0, 0);
    for seed in 0..20u64 {
        // 300 beats, low and moderate HRV
        let (mean, rsa, noise) = if seed % 2 == 0 {
            (650.0, 9.0, 4.0)
        } else {
            (800.0, 20.0, 8.0)
        };
        let truth = sinus(seed, 300, mean, rsa, 12.0, noise);
        let (x, events, epos) = inject(&truth, 9, 3, seed); // 3 % ectopy, 1 % artifacts
        let out = classify_beats(&x, FS, &params, None).unwrap();
        for i in ectopic_inputs(&x, &epos) {
            n_ect += 1;
            assert_eq!(
                out.input_classes[i],
                BeatClass::Ectopic,
                "seed {seed}: injected ectopic input beat {i}"
            );
            // both adjacent NN excluded, the beat is not moved
            let j = out.input_to_output[i].unwrap();
            assert_eq!(out.positions[j].to_bits(), x[i].to_bits());
            assert!(!out.nn_valid[j - 1] && !out.nn_valid[j]);
            n_hit += 1;
        }
        for &(kind, lo, hi) in events.iter().filter(|e| e.0 != Event::Ectopic) {
            n_art += 1;
            n_art_hit += caught(&out, &x, lo, hi) as usize;
            if kind == Event::Missed || kind == Event::Extra {
                assert!(caught(&out, &x, lo, hi), "seed {seed}: {kind:?} missed");
            }
        }
        // ectopy is recorded, not counted as artifact: the artifact ratio stays near the injected 1 %
        assert!(out.artifact_ratio() <= 0.04, "seed {seed}");
        assert!(out.kept_share() >= 0.75, "seed {seed}");
    }
    eprintln!(
        "injected ectopic beats classified Ectopic: {n_hit}/{n_ect}; artifacts acted on: {n_art_hit}/{n_art}"
    );
    assert_eq!(n_hit, n_ect);
}

fn rel_err(x: f64, truth: f64) -> f64 {
    ((x - truth) / truth).abs()
}

fn quantile(v: &[f64], q: f64) -> f64 {
    let mut s = v.to_vec();
    s.sort_by(f64::total_cmp);
    s[((s.len() - 1) as f64 * q).round() as usize]
}

/// HRV levels of the synthetic series: (mean RR, RSA, noise) in ms; RMSSD ≈ 10 / 20 / 40 ms.
const LEVELS: [(f64, f64, f64); 3] = [(650.0, 9.0, 4.0), (750.0, 18.0, 8.0), (850.0, 38.0, 15.0)];

/// At ≤ 3 % ectopy (+ 1 % missed / extra / jitter) on 300 beats, RMSSD from the masked NN stays
/// within 10 % of the true sinus RMSSD in every series. Kubios interpolation moves the premature
/// beat (and often a neighbour) to a midpoint, leaving 50–100 ms steps: its RMSSD error is many
/// times larger (this is why the exclusion mode exists).
#[test]
fn masked_rmssd_close_to_truth_interpolation_is_not() {
    let params = ExclusionParams::default();
    let (mut masked, mut interp, mut interp_low) = (vec![], vec![], vec![]);
    let mut worse = 0;
    for (li, &(mean, rsa, noise)) in LEVELS.iter().enumerate() {
        for seed in 0..20u64 {
            let truth = sinus(seed + 100 * li as u64, 300, mean, rsa, 12.0, noise);
            let rt = compute_rmssd(&rri_from_positions(&truth, FS));
            let (x, _, _) = inject(&truth, 9, 3, seed + 1000);
            let out = classify_beats(&x, FS, &params, None).unwrap();
            let em = rel_err(out.rmssd().unwrap(), rt);
            let k = fix_positions_with(&x, FS, &KubiosParams::default()).unwrap();
            let ei = rel_err(compute_rmssd(&k.rri_ms(FS)), rt);
            assert!(
                em <= 0.10,
                "level {li} seed {seed}: masked RMSSD error {:.1} %",
                100.0 * em
            );
            worse += (ei > em) as usize;
            masked.push(em);
            interp.push(ei);
            if li == 0 {
                interp_low.push(ei);
            }
        }
    }
    let n = masked.len();
    eprintln!(
        "RMSSD |relative error| over {n} series (3 % ectopy + 1 % artifacts, 300 beats): masked median {:.1} % p90 {:.1} % max {:.1} %; Kubios interpolation median {:.1} % p90 {:.1} % (RMSSD ~10 ms: median {:.0} %)",
        100.0 * quantile(&masked, 0.5),
        100.0 * quantile(&masked, 0.9),
        100.0 * quantile(&masked, 1.0),
        100.0 * quantile(&interp, 0.5),
        100.0 * quantile(&interp, 0.9),
        100.0 * quantile(&interp_low, 0.5),
    );
    assert!(quantile(&interp, 0.5) >= 0.20);
    assert!(
        quantile(&interp_low, 0.5) >= 1.0,
        "low HRV: RMSSD at least doubled"
    );
    assert!(quantile(&interp, 0.5) >= 10.0 * quantile(&masked, 0.5));
    assert_eq!(worse, n, "interpolation is worse in every series");
}

/// At 8 % ectopy the ectopic dRR inflate the quartile thresholds and single-stage detection goes
/// blind to the remaining artifacts; the second pass on the copy with the ectopic beats at their
/// neighbours' midpoint finds them again.
///
/// - With the pattern rule (default) both stages find the ectopic beats; single-stage misses most
///   extra beats and jitter, and its RMSSD error explodes.
/// - With Kubios flags only (`premature_factor = 0`), single-stage also misses many ectopic beats;
///   two-stage excludes most of them (as stage-2 suspects).
#[test]
fn two_stage_catches_what_single_stage_misses_at_high_ectopy() {
    let mut caught_art = [0usize; 2];
    let mut n_art = 0;
    let mut err: [Vec<f64>; 2] = [vec![], vec![]];
    let mut ect_excl = [[0usize; 2]; 2]; // [pattern on/off][single/two]
    let mut n_ect = [0usize; 2];
    for seed in 0..30u64 {
        for (li, &(mean, rsa, noise)) in LEVELS[..2].iter().enumerate() {
            let truth = sinus(seed + 100 * li as u64, 300, mean, rsa, 12.0, noise);
            let rt = compute_rmssd(&rri_from_positions(&truth, FS));
            let (x, events, epos) = inject(&truth, 24, 6, seed + 2000); // 8 % + 2 %
            for (pi, premature_factor) in [0.85, 0.0].into_iter().enumerate() {
                let two = ExclusionParams {
                    premature_factor,
                    ..Default::default()
                };
                let one = ExclusionParams {
                    two_stage: false,
                    ..two
                };
                let outs = [
                    classify_beats(&x, FS, &one, None).unwrap(),
                    classify_beats(&x, FS, &two, None).unwrap(),
                ];
                for (s, o) in outs.iter().enumerate() {
                    for i in ectopic_inputs(&x, &epos) {
                        let j = o.input_to_output[i].unwrap();
                        ect_excl[pi][s] += (!o.nn_valid[j - 1] && !o.nn_valid[j]) as usize;
                    }
                    if pi == 0 {
                        err[s].push(rel_err(o.rmssd().unwrap(), rt));
                        for &(_, lo, hi) in events.iter().filter(|e| e.0 != Event::Ectopic) {
                            caught_art[s] += caught(o, &x, lo, hi) as usize;
                        }
                    }
                }
                n_ect[pi] += epos.len();
            }
            n_art += events.iter().filter(|e| e.0 != Event::Ectopic).count();
        }
    }
    let share = |a: usize, b: usize| a as f64 / b as f64;
    eprintln!(
        "8 % ectopy + 2 % artifacts, 60 series of 300 beats:\n  artifacts acted on: single {}/{n_art}, two-stage {}/{n_art}\n  RMSSD error median / p90: single {:.1} / {:.1} %, two-stage {:.1} / {:.1} %\n  ectopic beats with both NN excluded, pattern rule on: single {}/{}, two-stage {}/{}\n  ectopic beats with both NN excluded, Kubios flags only: single {}/{}, two-stage {}/{}",
        caught_art[0],
        caught_art[1],
        100.0 * quantile(&err[0], 0.5),
        100.0 * quantile(&err[0], 0.9),
        100.0 * quantile(&err[1], 0.5),
        100.0 * quantile(&err[1], 0.9),
        ect_excl[0][0],
        n_ect[0],
        ect_excl[0][1],
        n_ect[0],
        ect_excl[1][0],
        n_ect[1],
        ect_excl[1][1],
        n_ect[1],
    );
    // pattern rule: every ectopic beat excluded by both
    assert!(share(ect_excl[0][0], n_ect[0]) >= 0.99);
    assert!(share(ect_excl[0][1], n_ect[0]) >= 0.99);
    // artifacts hidden by the inflated thresholds
    assert!(share(caught_art[1], n_art) >= 0.85);
    assert!(share(caught_art[0], n_art) <= 0.70);
    // RMSSD
    assert!(quantile(&err[1], 0.5) <= 0.05);
    assert!(quantile(&err[1], 0.9) <= 0.15);
    assert!(quantile(&err[0], 0.5) >= 0.20);
    // Kubios flags only: single-stage misses ectopic beats that two-stage excludes
    let (s1, s2) = (
        share(ect_excl[1][0], n_ect[1]),
        share(ect_excl[1][1], n_ect[1]),
    );
    assert!(s1 <= 0.75 && s2 >= 0.75 && s2 - s1 >= 0.15, "{s1} {s2}");
}

/// All-valid NN: the masked RMSSD is the ordinary RMSSD (bit for bit); too few valid pairs: `None` /
/// `NaN`.
#[test]
fn masked_rmssd_all_valid_and_too_few_pairs() {
    let truth = sinus(3, 300, 750.0, 18.0, 12.0, 8.0);
    let out = classify_beats(&truth, FS, &ExclusionParams::default(), None).unwrap();
    assert!(out.nn_valid.iter().all(|&v| v));
    let rr = rri_from_positions(&truth, FS);
    assert_eq!(out.rmssd().unwrap().to_bits(), compute_rmssd(&rr).to_bits());
    let td = out.time_domain();
    assert_eq!(td.time, fast_hrv::time_domain(&rr));
    assert_eq!((td.n_nn, td.n_pairs), (299, 298));

    // every second beat ectopic-like (bigeminy): no two adjacent NN survive
    let mut big = truth.clone();
    for k in (2..big.len() - 2).step_by(2) {
        big[k] -= 0.3 * (truth[k] - truth[k - 1]);
    }
    let out = classify_beats(&big, FS, &ExclusionParams::default(), None).unwrap();
    let td = out.time_domain();
    eprintln!(
        "bigeminy: kept {} of {} NN, {} pairs",
        out.kept_count(),
        out.usable_count(),
        td.n_pairs
    );
    assert!(td.n_pairs < 2);
    assert_eq!(out.rmssd(), None);
    assert!(td.time.rmssd.is_nan());
}

/// Segments: `concat_nn` puts a NaN / invalid entry between segments, so no successive difference
/// spans the gap.
#[test]
fn segments_do_not_mix() {
    let a = sinus(1, 200, 750.0, 18.0, 12.0, 8.0);
    let b: Vec<f64> = sinus(2, 200, 600.0, 9.0, 12.0, 4.0)
        .iter()
        .map(|p| p + a.last().unwrap() + 60.0 * FS)
        .collect();
    let outs = fast_hrv::classify_segments(
        &[a.clone(), b.clone()],
        FS,
        &ExclusionParams::default(),
        None,
    )
    .unwrap();
    let (nn, valid) = fast_hrv::concat_nn(&outs);
    assert_eq!(nn.len(), 199 + 1 + 199);
    assert!(nn[199].is_nan() && !valid[199]);
    let m = fast_hrv::time_domain_masked(&nn, &valid);
    // expected: the differences of each segment on its own
    let d: Vec<f64> = outs
        .iter()
        .flat_map(|o| fast_hrv::masked_differences(&o.nn_ms(), &o.nn_valid))
        .collect();
    let want = (d.iter().map(|x| x.powi(2)).sum::<f64>() / d.len() as f64).sqrt();
    assert_eq!(m.n_pairs, d.len());
    assert!(d.len() >= 390);
    assert_eq!(m.time.rmssd.to_bits(), want.to_bits());
}
